/** Firing order from the docs. STELLA_PHASES is already in this order. */
export const STELLA_FIRING_ORDER: string[] = ["F1", "F1b", "F1c", "F2", "F2b", "F2c", "F3", "Q1", "X1", "P1", "D1", "P2", "M1", "W1", "W2", "B1", "B2", "E1", "E2", "E3", "E4", "U1", "V1", "V2", "V3", "A1", "C1", "H1", "H2"];

/**
 * Compose the prompt to paste for one mode, phase and variant.
 *
 * - 'full': preamble (first line set to the phase) + phase prompt.
 * - 'fix': preamble (first line set to the phase) + fix-round prompt.
 * - 'phase': the phase prompt alone, with no preamble.
 *
 * Everything except the preamble first line is returned exactly as stored.
 */
export function composeStellaPrompt(
	modeId: StellaModeId,
	phaseId: string,
	variantId: StellaVariantId,
): string {
	const mode: StellaModePrompts | undefined = STELLA_MODES[modeId];
	const phase: StellaPhase | undefined = STELLA_PHASES.find((p) => p.id === phaseId);
	if (!mode) throw new Error(`Unknown Stella mode: ${modeId}`);
	if (!phase) throw new Error(`Unknown Stella phase: ${phaseId}`);
	if (variantId === 'phase') return phase.body;
	const lines = mode.preamble.split('\n');
	if (lines[0] !== STELLA_PHASE_ID_PLACEHOLDER) {
		throw new Error('Stella preamble changed: its first line is not the PHASE_ID placeholder.');
	}
	lines[0] = `PHASE_ID: ${phase.id}`;
	const preamble = lines.join('\n');
	if (variantId === 'full') return `${preamble}\n\n${phase.body}`;
	if (variantId === 'fix') return `${preamble}\n\n${mode.fixPrompt}`;
	throw new Error(`Unknown Stella variant: ${variantId}`);
}
